import{_ as e,a as o,b as a}from"./chunks/steamdeck-3.BwF2MKE5.js";import{_ as s,o as n,c as r,a5 as i}from"./chunks/framework.BjM_ivYE.js";const b=JSON.parse('{"title":"Steam Deck reset & reinstall","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/steamdeck-setup.md","filePath":"manual/troubleshooting/steamdeck-setup.md","lastUpdated":1789720001000}'),l={name:"manual/troubleshooting/steamdeck-setup.md"};function c(d,t,p,h,m,g){return n(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="steam-deck-reset-reinstall" tabindex="-1">Steam Deck reset &amp; reinstall <a class="header-anchor" href="#steam-deck-reset-reinstall" aria-label="Permalink to &quot;Steam Deck reset &amp; reinstall&quot;">​</a></h1><p>The Steam Deck ships fully configured, so this procedure is not normally needed. Follow it after a factory reset, or to install the RBQ app on a Steam Deck of your own. It also gets you back to a known state when the controller will not boot properly or its configuration has been messed up.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>A factory reset <strong>erases all user data and configuration and reinstalls SteamOS</strong>. Back up your settings and files first.</p></div></div><h2 id="factory-reset" tabindex="-1">1. Factory reset <a class="header-anchor" href="#factory-reset" aria-label="Permalink to &quot;1. Factory reset {#factory-reset}&quot;">​</a></h2><p>If the device still boots normally, you can restore it to factory state from the OS settings.</p><ol><li>Press the <strong>Steam</strong> button.</li><li>Select <strong>Settings</strong>.</li><li>Go to the <strong>System</strong> tab.</li><li>Scroll to the bottom and select <strong>Factory reset</strong> under <strong>Advanced</strong>.</li><li>Press the <strong>Factory Reset</strong> button to confirm.</li></ol><p>When the reset finishes, create a Steam account and sign in.</p><h2 id="desktop-mode" tabindex="-1">2. Switch to desktop mode <a class="header-anchor" href="#desktop-mode" aria-label="Permalink to &quot;2. Switch to desktop mode {#desktop-mode}&quot;">​</a></h2><ol><li>Press the <strong>Steam</strong> button.</li><li>Select the <strong>Power</strong> menu.</li><li>Press <strong>Switch to Desktop</strong>.</li></ol><h2 id="download" tabindex="-1">3. Download the app <a class="header-anchor" href="#download" aria-label="Permalink to &quot;3. Download the app {#download}&quot;">​</a></h2><p>In desktop mode, open the <a href="/RBQ/manual/downloads/">Downloads</a> page in a browser and download <strong>RBQ Controller (Linux · Steam Deck)</strong>. The file is <code>rbq-controller-x86_64.AppImage</code>.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p><strong>This first download can go in any folder.</strong> Run it once as described below, then press <strong>Install online</strong> inside the app: it creates its own install folder under <code>/home/deck/Documents/RBQ/</code> and points a <code>latest</code> link at it. Later updates only move that link, so <strong>the shortcut you add to Steam keeps working.</strong></p></div></div><h2 id="permission" tabindex="-1">4. Make it executable <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;4. Make it executable {#permission}&quot;">​</a></h2><p>Once downloaded, right-click <code>rbq-controller-x86_64.AppImage</code>, go to <strong>Properties → Permissions</strong>, and tick <strong>Is executable</strong>.</p><figure><img src="'+e+'" alt="Selecting Properties from the AppImage right-click menu"><figcaption style="text-align:center;">Right-click → Properties</figcaption></figure><figure><img src="'+o+'" alt="Ticking the executable permission on the Permissions tab"><figcaption style="text-align:center;">Permissions → Is executable</figcaption></figure><h2 id="add-to-steam" tabindex="-1">5. Add it to Steam <a class="header-anchor" href="#add-to-steam" aria-label="Permalink to &quot;5. Add it to Steam {#add-to-steam}&quot;">​</a></h2><p>Right-click the same file again and choose <strong>Add to Steam</strong>.</p><figure><img src="'+a+'" alt="Selecting Add to Steam from the AppImage right-click menu"><figcaption style="text-align:center;">Right-click → Add to Steam</figcaption></figure><h2 id="launch" tabindex="-1">6. Boot into SteamOS and launch <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;6. Boot into SteamOS and launch {#launch}&quot;">​</a></h2><ol><li>Use the <strong>Steam icon</strong> at the bottom left → <strong>Shut Down</strong>, then boot back into SteamOS.</li><li>Press the <strong>STEAM</strong> button at the bottom left and go to <strong>Library → Non-Steam</strong>.</li><li>Launch <strong>rbq-controller</strong> from the list.</li></ol><p>Once the app is up, press <strong>Install online</strong> under <strong>Robot settings → Software update</strong> to create the install folder — app updates then happen from that same screen.</p><p>For connecting to the robot from here, see <a href="/RBQ/manual/operation/controller-wifi-connect.html">Controller and Wi-Fi Connection</a>.</p>',23)])])}const k=s(l,[["render",c]]);export{b as __pageData,k as default};
